      "mode.undecided": "Not yet decided",
      "context.note": "When working, select your current job instead of your department. In other situations, existing department/career search results are maintained.",
      "selection.title": "Select your current job",
      "selection.intro": "Narrow by job field or search by job name or classification code. If your actual duties are different, you can supplement them by entering them directly.",
      "selection.count": "Select based on 35 fields, 140 job groups, and 495 detailed occupations in the Korea Employment Classification of Occupations 2025. Job classifications are not job fit criteria or employment evaluation scores.",
      "selection.group": "Job field",
      "selection.all": "entire field",
      "selection.search": "Search by job name or code",
      "selection.results": "{count} search results",
      "selection.job": "Current job/occupation",
      "selection.placeholder": "Choose a job",
      "selection.other": "Others — enter directly",
      "selection.titleLabel": "actual job title",
      "selection.titleHelp": "Required when selecting others. Please enter the job title of your organization. Up to 120 characters.",
      "selection.tasks": "Responsibilities (optional)",
      "selection.tasksHelp": "Examples: airport security screening, airline security work, air cargo security, industrial security control. Do not enter your name, confidential company information, or personal information. Up to 800 characters.",
      "selection.apply": "job application",
      "selection.error": "Select a job, and if other, enter the actual job title.",
      "selection.applied": "The job has been applied to the current result sheet.",
      "selection.pending": "Your current job has not been selected yet. Your job selection will be reflected in the work action plan below.",
