      "selection.classification": "Job classification: {group} / {job} ({code})",
      "selection.record": "Responsibility: {tasks}",
      "selection.noTasks": "Try out the method below by choosing one task that you frequently perform in your chosen job.",
      "selection.noFit": "Verified requirements scores for the selected job are not linked to produce a fit percentage or job ranking. Department scores are not displayed as job suitability instead.",
      "selection.source": "Occupational Classification Source: Ministry of Employment and Labor, Korea Employment Classification of Occupations 2025",
      "work.overview": "Current job and cognitive characteristics",
      "work.methods": "What to try in your current job",
      "work.plan": "business execution plan",
      "work.capabilities": "Inspection of work support by cognitive area",
      "work.growth": "Record and coordinate work attempts",
