      "work.efficiency": "Check your work methods",
      "work.support": "Support for adapting to work",
      "work.faq": "Information on results for current employees",
      "work.about": "Use of employee result sheet",
      "work.header": "{age} years old · Currently employed · Examination date {date}",
      "work.cover": "Choose a method to use in your current job and adapt it with real-world work experience.",
      "work.hook": "Find out how we can help you with your current job and the additional support you need.",
      "work.taskPrompt": "{job} Tasks to attempt first during work",
      "work.methodPrompt": "{job} Approach to apply to work",
      "work.step1": "Pick one recurring task and write down the criteria for its completion. Check safety regulations and site instructions first.",
      "work.step2": "Experiment with one of the methods below and note how long it took, what you missed, what you reworked, and whether you asked for help. Even areas with relatively high scores do not mean that work ability is confirmed.",
      "work.step3": "Compare with previous records on the same task, and if the burden is high, reduce the number of steps or ask for help from materials or colleagues. Decide one thing to change on your next attempt.",
      "work.recordTemplate": "Work situation → Method I tried → Observation results → Help received → What to change next time. Only actual experiences are recorded and test scores are not expressed as performance or achievements.",
      "work.supportText": "The score is the pattern of processing observed in the current examination. One score does not determine job performance ability or growth potential. Take a look at your work experience, education, environment, and support you need.",
      "work.sharing": "Even when using it in a company, do not make hiring, placement, or personnel evaluation decisions based solely on these results. Check work-related materials and interviews together, and inform yourself of the scope of sharing the results.",
