      "selection.title": "現在の職務を選択",
      "selection.intro": "職務分野に絞ったり、職名・分類コードで検索してください。実際の担当業務が異なる場合は、直接入力して補完することができます。",
      "selection.count": "韓国雇用職業分類 2025の35分野・140の職務群・495の細部職業に基づいて選択します。職業分類は、職務適合度基準や採用評価スコアではありません。",
      "selection.group": "職業分野",
      "selection.all": "全分野",
      "selection.search": "ジョブ名またはコード検索",
