      "selection.job": "現在の職務・職業",
      "selection.placeholder": "職務を選択してください",
      "selection.other": "その他 — 直接入力",
      "selection.titleLabel": "実際の職務名",
      "selection.titleHelp": "その他の選択に必須です。所属組織の職務名を入力してください。最大120文字。",
      "selection.tasks": "担当業務（選択）",
      "selection.tasksHelp": "例：空港セキュリティ検索、航空会社セキュリティ事務、航空貨物セキュリティ、産業セキュリティ管理。氏名・会社の機密・個人情報は入力しないでください。最大800文字。",
      "selection.apply": "職務の適用",
      "selection.error": "職務を選択し、その他の場合は実際の職務名を入力してください。",
      "selection.applied": "現在、結果紙に職務を適用しました。",
      "selection.pending": "まだ現在の職務は選択されていません。職務を選択すると、以下の業務実行計画に反映されます。",
      "selection.current": "現在の職務: {job}",
      "selection.classification": "職業分類: {group} / {job} ({code})",
      "selection.record": "担当業務: {tasks}",
      "selection.noTasks": "選択した職務で頻繁に担当する業務の1つを決めて、以下の方法を試してみてください。",
      "selection.noFit": "選択した職務の実績のある要求スコアがリンクされていないため、適合度もパーセンテージや職務順位を生成しません。学科スコアを職務適合度として代わりに表示しません。",
      "selection.source": "職業分類ソース：雇用労働部、韓国雇用職業分類2025",
