      "work.growth": "仕事の試み記録と調整",
      "work.roadmap": "業務適応・成長計画",
      "work.evidence": "業務経験記録",
      "work.efficiency": "業務方法の確認",
      "work.support": "業務適応のための支援",
      "work.faq": "在職者結果紙案内",
      "work.about": "在職者結果誌の活用",
      "work.header": "のみ{age}歳・在職中・検査日{date}",
      "work.cover": "現在の職務で使用する方法を選択し、実務経験に合わせて調整します。",
      "work.hook": "現在の仕事で役立つ方法と、必要な支援を一緒に見つけてください。",
      "work.taskPrompt": "{job}仕事中に最初に試みる課題",
      "work.methodPrompt": "{job} 仕事に適用するアプローチ",
      "work.step1": "繰り返される業務の一つを選び、完了基準を書く。安全規則と現場の指示を最初に確認してください。",
      "work.step2": "以下のいずれかの方法をテストし、所要時間、行方不明、再作業、ヘルプ要求を記録します。スコアが比較的高い領域も、業務能力が確定したという意味ではありません。",
      "work.step3": "同じ業務で以前の記録と比較し、負担が大きいとステップ数を減らしたり、資料・仲間の助けを求めます。次の試みで変更する1つの点を決めてください。",
      "work.recordTemplate": "仕事の状況→私が試した方法→観察した結果→受け取った助け→次に変える点。実際の経験だけを記録し、検査スコアをパフォーマンスやパフォーマンスで表現することはありません。",
      "work.supportText": "スコアは、現在の検査で観察された処理面です。 1つのスコアで職務を遂行する能力や成長の可能性を決定することはありません。仕事の経験、教育、環境、必要なサポートを一緒に見てください。",
      "work.sharing": "企業で活用するときも、この結果だけで採用・配置・人事評価を決定しないでください。業務関連資料と面談を一緒に確認し、結果の共有範囲はご自身にご案内ください。",
      "work.noRanking": "現在の職務選択は推奨職務TOP5や採用適合度判定ではありません。実際に担当することに基づいて支援方法と実行計画を決める機能です。",
      "work.restore": "在学生・就職準備・まだ未定に変えると、以前に選択した学科と既存の進路ナビゲーション画面を見直すことができます。",
      "work.chooseFirst": "まず、現在の職務を選択してください。認知スコアと81タイプは状況選択に変わりません。",
