      "work.faq": "有关现任员工结果的信息",
      "work.about": "使用员工成绩单",
      "work.header": "{age} 岁 · 目前在职 · 考试日期 {date}",
      "work.cover": "选择一种在您当前工作中使用的方法，并根据实际工作经验进行调整。",
      "work.hook": "了解我们如何帮助您完成当前的工作以及您需要的额外支持。",
      "work.taskPrompt": "{job} 工作期间首先尝试的任务",
      "work.methodPrompt": "{job} 申请工作的方法",
      "work.step1": "选择一项重复任务并写下其完成标准。首先检查安全规定和现场说明。",
      "work.step2": "尝试以下方法之一，并记下花费了多长时间、错过了什么、返工了什么以及是否寻求帮助。即使是得分比较高的领域，也不代表工作能力得到了确认。",
      "work.step3": "与同一任务的以往记录进行比较，如果负担较大，则减少步骤数或向材料或同事寻求帮助。决定在下次尝试时改变一件事。",
      "work.recordTemplate": "工作情况→我尝试的方法→观察结果→收到的帮助→下次要改变什么。仅记录实际经验，测试分数不表示为表现或成就。",
      "work.supportText": "分数是当前考试中观察到的处理模式。一项分数并不能决定工作表现能力或成长潜力。看看您的工作经验、教育、环境和您需要的支持。",
      "work.sharing": "即使在公司中使用它，也不要仅根据这些结果做出招聘、安置或人员评估决策。一起检查与工作相关的材料和访谈，并了解共享结果的范围。",
      "work.noRanking": "当前的职位选择不是前 5 名推荐职位，也不是招聘适合性的确定。这是根据实际分配的工作确定支持方法和行动计划的功能。",
      "work.restore": "如果更改为“当前学生”、“准备就业”或“尚未确定”，您可以再次看到之前选择的部门和现有职业路径搜索屏幕。",
      "work.chooseFirst": "首先，请选择您当前的工作。认知分数和 81 型不会随情境选择而改变。",
