      "work.step1": "選擇一項重複任務並寫下其完成標準。首先檢查安全規定和現場說明。",
      "work.step2": "嘗試以下方法之一，並記下花費了多長時間、錯過了什麼、返工了什麼以及是否尋求幫助。即使是得分比較高的領域，也不代表工作能力得到了確認。",
      "work.step3": "與相同任務的以往記錄進行比較，如果負擔較大，則減少步驟數或向材料或同事尋求協助。決定在下次嘗試時改變一件事。",
      "work.recordTemplate": "工作狀況→我嘗試的方法→觀察結果→收到的幫助→下次改變什麼。僅記錄實際經驗，測驗分數不表示為表現或成就。",
