      "work.capabilities": "Inspección del apoyo al trabajo por área cognitiva.",
      "work.growth": "Registrar y coordinar intentos de trabajo.",
      "work.roadmap": "Plan de adaptación/crecimiento laboral",
      "work.evidence": "registro de experiencia laboral",
      "work.efficiency": "Comprueba tus métodos de trabajo",
      "work.support": "Apoyo para la adaptación al trabajo",
      "work.faq": "Información sobre resultados de los empleados actuales.",
      "work.about": "Uso de la hoja de resultados del empleado",
      "work.header": "{age} años · Actualmente empleado · Fecha de examen {date}",
      "work.cover": "Elija un método para utilizar en su trabajo actual y adáptelo con la experiencia laboral del mundo real.",
      "work.hook": "Descubra cómo podemos ayudarle con su trabajo actual y el apoyo adicional que necesita.",
      "work.taskPrompt": "{job} Tareas a intentar primero durante el trabajo",
      "work.methodPrompt": "{job} Enfoque para postularse al trabajo",
      "work.step1": "Elija una tarea recurrente y escriba los criterios para completarla. Consulte primero las normas de seguridad y las instrucciones del sitio.",
      "work.step2": "Experimente con uno de los métodos siguientes y observe cuánto tiempo le llevó, qué se perdió, qué modificó y si pidió ayuda. Incluso las áreas con puntuaciones relativamente altas no significan que se confirme la capacidad laboral.",
      "work.step3": "Comparar con registros anteriores de la misma tarea, y si la carga es alta, reducir el número de pasos o pedir ayuda a materiales o compañeros. Decide una cosa para cambiar en tu próximo intento.",
      "work.recordTemplate": "Situación laboral → Método que probé → Resultados de la observación → Ayuda recibida → Qué cambiar la próxima vez. Sólo se registran las experiencias reales y los puntajes de las pruebas no se expresan como desempeño o logros.",
      "work.supportText": "La puntuación es el patrón de procesamiento observado en el examen actual. Una puntuación no determina la capacidad de desempeño laboral ni el potencial de crecimiento. Eche un vistazo a su experiencia laboral, educación, entorno y el apoyo que necesita.",
      "work.sharing": "Incluso cuando lo utilice en una empresa, no tome decisiones de contratación, colocación o evaluación de personal basándose únicamente en estos resultados. Consulten juntos materiales relacionados con el trabajo y entrevistas, e infórmese sobre el alcance de compartir los resultados.",
      "work.noRanking": "La selección de trabajo actual no es uno de los 5 trabajos recomendados ni una determinación de idoneidad para la contratación. Esta es una función que determina el método de soporte y el plan de acción en función del trabajo real asignado.",
      "work.restore": "Si cambia a Estudiante actual, Preparándose para el empleo o Aún no determinado, podrá ver nuevamente el departamento seleccionado previamente y la pantalla de búsqueda de trayectoria profesional existente.",
      "work.chooseFirst": "Primero, seleccione su trabajo actual. Las puntuaciones cognitivas y el Tipo 81 no cambian con la selección situacional.",
