      "selection.titleHelp": "Bắt buộc khi chọn người khác. Vui lòng nhập chức danh công việc của tổ chức bạn. Lên đến 120 ký tự.",
      "selection.tasks": "Trách nhiệm (tùy chọn)",
      "selection.tasksHelp": "Ví dụ: soi chiếu an ninh sân bay, công tác an ninh hàng không, an ninh hàng hóa hàng không, kiểm soát an ninh công nghiệp. Không nhập tên của bạn, thông tin bí mật của công ty hoặc thông tin cá nhân. Lên đến 800 ký tự.",
