      "selection.noFit": "Điểm yêu cầu đã được xác minh cho công việc đã chọn không được liên kết để tạo ra tỷ lệ phần trăm phù hợp hoặc xếp hạng công việc. Thay vào đó, điểm của bộ phận không được hiển thị dưới dạng mức độ phù hợp với công việc.",
