      "work.header": "{age} tuổi · Hiện đang làm việc · Ngày thi {date}",
      "work.cover": "Chọn một phương pháp để sử dụng trong công việc hiện tại của bạn và điều chỉnh nó cho phù hợp với kinh nghiệm làm việc thực tế.",
      "work.hook": "Tìm hiểu cách chúng tôi có thể giúp bạn với công việc hiện tại và sự hỗ trợ bổ sung mà bạn cần.",
      "work.taskPrompt": "{job} Nhiệm vụ cần thực hiện đầu tiên trong quá trình làm việc",
      "work.methodPrompt": "{job} Phương pháp xin việc",
      "work.step1": "Chọn một nhiệm vụ định kỳ và viết ra các tiêu chí để hoàn thành nó. Kiểm tra các quy định an toàn và hướng dẫn trang web đầu tiên.",
      "work.step2": "Hãy thử nghiệm một trong các phương pháp bên dưới và ghi lại thời gian thực hiện, những gì bạn đã bỏ lỡ, những gì bạn đã làm lại và liệu bạn có yêu cầu trợ giúp hay không. Ngay cả những lĩnh vực có điểm số tương đối cao cũng không có nghĩa là khả năng làm việc được khẳng định.",
      "work.step3": "So sánh với các bản ghi trước đó về cùng một nhiệm vụ và nếu gánh nặng cao, hãy giảm số bước hoặc yêu cầu sự trợ giúp từ tài liệu hoặc đồng nghiệp. Quyết định một điều cần thay đổi trong lần thử tiếp theo của bạn.",
      "work.recordTemplate": "Tình hình công việc → Phương pháp tôi đã thử → Kết quả quan sát → Nhận được trợ giúp → Những gì cần thay đổi vào lần tới. Chỉ những trải nghiệm thực tế mới được ghi lại và điểm kiểm tra không được thể hiện dưới dạng hiệu suất hoặc thành tích.",
      "work.supportText": "Điểm số là mô hình xử lý được quan sát trong kỳ thi hiện tại. Một điểm số không quyết định khả năng thực hiện công việc hoặc tiềm năng phát triển. Hãy xem xét kinh nghiệm làm việc, trình độ học vấn, môi trường và sự hỗ trợ mà bạn cần.",
      "work.sharing": "Ngay cả khi sử dụng nó trong công ty, đừng đưa ra quyết định tuyển dụng, bố trí hoặc đánh giá nhân sự chỉ dựa trên những kết quả này. Cùng nhau kiểm tra các tài liệu liên quan đến công việc và các cuộc phỏng vấn, đồng thời thông báo cho bản thân về phạm vi chia sẻ kết quả.",
      "work.noRanking": "Việc lựa chọn công việc hiện tại không phải là top 5 công việc được đề xuất hay xác định mức độ phù hợp để tuyển dụng. Đây là chức năng xác định phương thức hỗ trợ và kế hoạch hành động dựa trên công việc thực tế được giao.",
      "work.restore": "Nếu bạn thay đổi thành Sinh viên hiện tại, Đang chuẩn bị đi làm hoặc Chưa xác định, bạn có thể thấy lại bộ phận đã chọn trước đó và màn hình tìm kiếm lộ trình nghề nghiệp hiện có.",
      "work.chooseFirst": "Đầu tiên hãy chọn công việc hiện tại của bạn. Điểm nhận thức và Loại 81 không thay đổi khi lựa chọn tình huống.",
