      "context.note": "เมื่อทำงาน ให้เลือกงานปัจจุบันของคุณแทนแผนกของคุณ ในสถานการณ์อื่นๆ ผลการค้นหาแผนก/อาชีพที่มีอยู่จะยังคงอยู่",
      "selection.title": "เลือกงานปัจจุบันของคุณ",
      "selection.intro": "กรองตามสาขางานหรือค้นหาตามชื่องานหรือรหัสหมวดหมู่ หากหน้าที่ที่แท้จริงของคุณแตกต่างออกไป คุณสามารถเสริมได้โดยป้อนโดยตรง",
      "selection.count": "เลือกโดยพิจารณาจาก 35 สาขา กลุ่มงาน 140 กลุ่ม และอาชีพโดยละเอียด 495 รายการในการจัดประเภทอาชีพของเกาหลีในปี 2025 การจัดประเภทงานไม่ใช่เกณฑ์ความเหมาะสมของงานหรือคะแนนการประเมินการจ้างงาน",
      "selection.group": "สาขางาน",
      "selection.all": "ทั้งสนาม",
      "selection.search": "ค้นหาตามชื่องานหรือรหัส",
      "selection.results": "{count} ผลการค้นหา",
      "selection.job": "งาน/อาชีพปัจจุบัน",
