      "selection.titleLabel": "ชื่องานที่แท้จริง",
      "selection.titleHelp": "จำเป็นเมื่อเลือกผู้อื่น กรุณากรอกตำแหน่งงานขององค์กรของคุณ สูงสุด 120 ตัวอักษร",
      "selection.tasks": "ความรับผิดชอบ (ไม่บังคับ)",
      "selection.tasksHelp": "ตัวอย่าง: การคัดกรองความปลอดภัยของสนามบิน งานรักษาความปลอดภัยของสายการบิน ความปลอดภัยในการขนส่งสินค้าทางอากาศ การควบคุมความปลอดภัยทางอุตสาหกรรม อย่ากรอกชื่อ ข้อมูลบริษัทที่เป็นความลับ หรือข้อมูลส่วนบุคคลของคุณ มากถึง 800 ตัวอักษร",
