      "selection.record": "ความรับผิดชอบ: {tasks}",
      "selection.noTasks": "ลองใช้วิธีการด้านล่างโดยเลือกหนึ่งงานที่คุณทำบ่อยๆ ในงานที่คุณเลือก",
      "selection.noFit": "คะแนนข้อกำหนดที่ตรวจสอบแล้วสำหรับงานที่เลือกไม่ได้เชื่อมโยงกับการสร้างเปอร์เซ็นต์ที่เหมาะสมหรือการจัดอันดับงาน คะแนนแผนกจะไม่แสดงตามความเหมาะสมของงานแทน",
      "selection.source": "การจำแนกประเภทอาชีพ ที่มา: กระทรวงการจ้างงานและแรงงาน ประเทศเกาหลี การจำแนกประเภทอาชีพปี 2025",
      "work.overview": "งานปัจจุบันและลักษณะทางปัญญา",
      "work.methods": "สิ่งที่ต้องลองในงานปัจจุบันของคุณ",
