      "work.growth": "บันทึกและประสานงานความพยายามในการทำงาน",
      "work.roadmap": "การปรับตัว/แผนการเติบโตในการทำงาน",
      "work.evidence": "บันทึกประสบการณ์การทำงาน",
      "work.efficiency": "ตรวจสอบวิธีการทำงานของคุณ",
      "work.support": "รองรับการปรับตัวเข้ากับการทำงาน",
      "work.faq": "ข้อมูลผลลัพธ์สำหรับพนักงานปัจจุบัน",
      "work.about": "การใช้เอกสารแสดงผลการทำงานของพนักงาน",
      "work.header": "{age} ปี · ทำงานอยู่ในปัจจุบัน · วันสอบ {date}",
      "work.cover": "เลือกวิธีการใช้ในงานปัจจุบันของคุณและปรับให้เข้ากับประสบการณ์การทำงานจริง",
      "work.hook": "ค้นหาวิธีที่เราสามารถช่วยเหลือคุณกับงานปัจจุบันของคุณและการสนับสนุนเพิ่มเติมที่คุณต้องการ",
      "work.taskPrompt": "{job} งานที่ต้องลองก่อนระหว่างทำงาน",
      "work.methodPrompt": "{job} แนวทางการสมัครงาน",
      "work.step1": "เลือกงานที่เกิดซ้ำหนึ่งงานและจดเกณฑ์ความสมบูรณ์ของงาน ตรวจสอบกฎระเบียบด้านความปลอดภัยและคำแนะนำในสถานที่ก่อน",
      "work.step2": "ทดลองด้วยวิธีใดวิธีหนึ่งด้านล่างและจดบันทึกว่าใช้เวลานานเท่าใด สิ่งที่คุณพลาดไป สิ่งที่คุณปรับปรุงใหม่ และคุณได้ขอความช่วยเหลือหรือไม่ แม้แต่พื้นที่ที่มีคะแนนค่อนข้างสูงก็ไม่ได้หมายความว่าจะยืนยันความสามารถในการทำงานได้",
      "work.step3": "เปรียบเทียบกับบันทึกก่อนหน้าในงานเดียวกัน และหากมีภาระสูง ให้ลดจำนวนขั้นตอนหรือขอความช่วยเหลือจากวัสดุหรือเพื่อนร่วมงาน ตัดสินใจสิ่งหนึ่งที่จะเปลี่ยนแปลงในความพยายามครั้งต่อไปของคุณ",
      "work.recordTemplate": "สถานการณ์การทำงาน → วิธีที่ฉันลอง → ผลการสังเกต → ความช่วยเหลือที่ได้รับ → สิ่งที่จะเปลี่ยนแปลงในครั้งต่อไป บันทึกเฉพาะประสบการณ์จริงเท่านั้น และคะแนนการทดสอบจะไม่แสดงเป็นผลงานหรือความสำเร็จ",
      "work.supportText": "คะแนนคือรูปแบบการประมวลผลที่พบในการสอบปัจจุบัน คะแนนหนึ่งคะแนนไม่ได้กำหนดความสามารถในการปฏิบัติงานหรือศักยภาพในการเติบโต ดูประสบการณ์การทำงาน การศึกษา สภาพแวดล้อม และการสนับสนุนที่คุณต้องการ",
      "work.sharing": "แม้ว่าจะใช้งานในบริษัทก็ตาม อย่าตัดสินใจจ้างงาน บรรจุตำแหน่ง หรือประเมินบุคลากรโดยพิจารณาจากผลลัพธ์เหล่านี้เพียงอย่างเดียว ตรวจสอบเอกสารที่เกี่ยวข้องกับงานและการสัมภาษณ์ร่วมกัน และแจ้งตัวเองถึงขอบเขตของการแบ่งปันผลลัพธ์",
      "work.noRanking": "การเลือกงานในปัจจุบันไม่ใช่งานแนะนำ 5 อันดับแรกหรือการพิจารณาความเหมาะสมในการรับสมัคร นี่คือฟังก์ชันที่กำหนดวิธีการสนับสนุนและแผนปฏิบัติการตามงานจริงที่ได้รับมอบหมาย",
      "work.restore": "หากคุณเปลี่ยนเป็นนักศึกษาปัจจุบัน กำลังเตรียมตัวเข้าทำงาน หรือยังไม่ได้กำหนด คุณสามารถดูแผนกที่เลือกไว้ก่อนหน้านี้และหน้าจอค้นหาเส้นทางอาชีพที่มีอยู่ได้อีกครั้ง",
