      "selection.count": "اختر بناءً على 35 مجالًا و140 مجموعة وظيفية و495 مهنة تفصيلية في تصنيف التوظيف للمهن في كوريا لعام 2025. تصنيفات الوظائف ليست معايير مناسبة للوظيفة أو درجات تقييم التوظيف.",
