      "selection.noTasks": "جرب الطريقة الموضحة أدناه عن طريق اختيار مهمة واحدة تقوم بها بشكل متكرر في الوظيفة التي اخترتها.",
      "selection.noFit": "لا يتم ربط درجات المتطلبات التي تم التحقق منها للوظيفة المحددة لإنتاج نسبة ملائمة أو تصنيف وظيفي. لا يتم عرض نتائج القسم كملاءمة للوظيفة بدلاً من ذلك.",
