      "work.about": "استخدام ورقة نتائج الموظف",
      "work.header": "{age} سنة · موظف حاليًا · تاريخ الامتحان {date}",
      "work.cover": "اختر طريقة لاستخدامها في وظيفتك الحالية وقم بتكييفها مع خبرة العمل الواقعية.",
      "work.hook": "اكتشف كيف يمكننا مساعدتك في وظيفتك الحالية والدعم الإضافي الذي تحتاجه.",
      "work.taskPrompt": "{job} المهام التي يجب تجربتها أولاً أثناء العمل",
      "work.methodPrompt": "{job} طريقة التقديم للعمل",
      "work.step1": "اختر مهمة متكررة واحدة واكتب المعايير اللازمة لإكمالها. تحقق من لوائح السلامة وتعليمات الموقع أولاً.",
      "work.step2": "قم بتجربة إحدى الطرق أدناه ولاحظ المدة التي استغرقتها، وما فاتك، وما قمت بإعادة صياغته، وما إذا كنت قد طلبت المساعدة. وحتى المناطق ذات الدرجات العالية نسبيًا لا تعني تأكيد القدرة على العمل.",
      "work.step3": "قارن مع السجلات السابقة لنفس المهمة، وإذا كان العبء كبيرا، قلل من عدد الخطوات أو اطلب المساعدة من المواد أو الزملاء. قرر شيئًا واحدًا لتغييره في محاولتك التالية.",
      "work.recordTemplate": "حالة العمل ← الطريقة التي جربتها ← نتائج المراقبة ← المساعدة المتلقاة ← ما الذي يجب تغييره في المرة القادمة. يتم تسجيل التجارب الفعلية فقط ولا يتم التعبير عن درجات الاختبار كأداء أو إنجازات.",
      "work.supportText": "النتيجة هي نمط المعالجة الذي لوحظ في الامتحان الحالي. درجة واحدة لا تحدد القدرة على الأداء الوظيفي أو إمكانات النمو. ألقِ نظرة على خبرتك في العمل والتعليم والبيئة والدعم الذي تحتاجه.",
      "work.sharing": "حتى عند استخدامه في شركة، لا تتخذ قرارات التوظيف أو التنسيب أو تقييم الموظفين بناءً على هذه النتائج فقط. قم بمراجعة المواد والمقابلات المتعلقة بالعمل معًا، وأطلع نفسك على نطاق مشاركة النتائج.",
      "work.noRanking": "إن اختيار الوظيفة الحالية ليس من أفضل 5 وظائف موصى بها أو تحديد مدى ملاءمتها للتوظيف. هذه هي الوظيفة التي تحدد طريقة الدعم وخطة العمل بناءً على الوظيفة الفعلية المعينة.",
      "work.restore": "إذا قمت بالتغيير إلى الطالب الحالي، أو التحضير للتوظيف، أو لم يتم التحديد بعد، فيمكنك رؤية القسم المحدد مسبقًا وشاشة البحث عن المسار الوظيفي الحالي مرة أخرى.",
      "work.chooseFirst": "أولا، الرجاء تحديد وظيفتك الحالية. لا تتغير النتائج المعرفية والنوع 81 مع اختيار الموقف.",
