      "work.efficiency": "Controlla i tuoi metodi di lavoro",
      "work.support": "Supporto per l'adattamento al lavoro",
      "work.faq": "Informazioni sui risultati per i dipendenti attuali",
      "work.about": "Utilizzo del foglio dei risultati dei dipendenti",
      "work.header": "{age} anni · Attualmente impiegato · Data dell'esame {date}",
      "work.cover": "Scegli un metodo da utilizzare nel tuo lavoro attuale e adattalo all'esperienza lavorativa nel mondo reale.",
      "work.hook": "Scopri come possiamo aiutarti con il tuo attuale lavoro e il supporto aggiuntivo di cui hai bisogno.",
      "work.taskPrompt": "{job} Attività da tentare per prime durante il lavoro",
      "work.methodPrompt": "{job} Approccio per candidarsi al lavoro",
      "work.step1": "Scegli un'attività ricorrente e scrivi i criteri per il suo completamento. Controllare prima le norme di sicurezza e le istruzioni del sito.",
      "work.step2": "Sperimenta uno dei metodi seguenti e nota quanto tempo ci è voluto, cosa ti sei perso, cosa hai rielaborato e se hai chiesto aiuto. Anche le aree con punteggi relativamente alti non significano che la capacità lavorativa sia confermata.",
      "work.step3": "Confronta con i record precedenti sulla stessa attività e, se il carico è elevato, riduci il numero di passaggi o chiedi aiuto ai materiali o ai colleghi. Decidi una cosa da cambiare al tuo prossimo tentativo.",
      "work.recordTemplate": "Situazione lavorativa → Metodo che ho provato → Risultati dell'osservazione → Aiuto ricevuto → Cosa cambiare la prossima volta. Vengono registrate solo le esperienze reali e i punteggi dei test non sono espressi come prestazioni o risultati.",
      "work.supportText": "Il punteggio è il modello di elaborazione osservato nell'esame corrente. Un punteggio non determina la capacità di prestazione lavorativa o il potenziale di crescita. Dai un'occhiata alla tua esperienza lavorativa, alla tua istruzione, all'ambiente e al supporto di cui hai bisogno.",
      "work.sharing": "Anche quando lo si utilizza in un'azienda, non prendere decisioni di assunzione, collocamento o valutazione del personale basate esclusivamente su questi risultati. Controllate insieme i materiali e le interviste relativi al lavoro e informatevi sull'ambito della condivisione dei risultati.",
      "work.noRanking": "L'attuale selezione del lavoro non è uno dei primi 5 lavori consigliati o una determinazione dell'idoneità per il reclutamento. Questa è una funzione che determina il metodo di supporto e il piano d'azione in base al lavoro effettivamente assegnato.",
      "work.restore": "Se passi a Studente attuale, In preparazione all'occupazione o Non ancora determinato, puoi visualizzare nuovamente la schermata di ricerca del dipartimento precedentemente selezionato e del percorso professionale esistente.",
      "work.chooseFirst": "Innanzitutto, seleziona il tuo lavoro attuale. I punteggi cognitivi e il Tipo 81 non cambiano con la selezione situazionale.",
