      "work.cover": "Cari işinizdə istifadə etmək üçün bir üsul seçin və onu real iş təcrübəsinə uyğunlaşdırın.",
      "work.hook": "Cari işinizdə və ehtiyacınız olan əlavə dəstəkdə sizə necə kömək edə biləcəyimizi öyrənin.",
