      "work.methodPrompt": "{job} İşə müraciət etmək üçün yanaşma",
      "work.step1": "Təkrarlanan tapşırıqlardan birini seçin və onun yerinə yetirilməsi üçün meyarları yazın. Əvvəlcə təhlükəsizlik qaydalarını və sayt təlimatlarını yoxlayın.",
      "work.step2": "Aşağıdakı üsullardan biri ilə sınaq keçirin və bunun nə qədər vaxt çəkdiyini, nəyi əldən verdiyinizi, nəyi yenidən işlədiyinizi və kömək istəməyinizi qeyd edin. Hətta nisbətən yüksək bal toplayan sahələr də iş qabiliyyətinin təsdiqlənməsi demək deyil.",
      "work.step3": "Eyni tapşırıq üzrə əvvəlki qeydlərlə müqayisə edin və yük yüksəkdirsə, addımların sayını azaldın və ya materiallardan və ya həmkarlarınızdan kömək istəyin. Növbəti cəhdinizdə dəyişdirmək üçün bir şeyə qərar verin.",
      "work.recordTemplate": "İş vəziyyəti → Sınadığım üsul → Müşahidə nəticələri → Alınan kömək → Növbəti dəfə nəyi dəyişmək lazımdır. Yalnız faktiki təcrübələr qeydə alınır və test xalları performans və ya nailiyyətlər kimi ifadə edilmir.",
      "work.supportText": "Bal cari imtahanda müşahidə olunan emal nümunəsidir. Bir xal iş qabiliyyətini və ya böyümə potensialını müəyyən etmir. İş təcrübənizə, təhsilinizə, ətrafınıza və sizə lazım olan dəstəyə nəzər salın.",
      "work.sharing": "Bir şirkətdə istifadə edərkən belə, yalnız bu nəticələrə əsaslanaraq işə götürmə, yerləşdirmə və ya kadrların qiymətləndirilməsi ilə bağlı qərarlar verməyin. İşlə bağlı materialları və müsahibələri birlikdə yoxlayın və nəticələrin paylaşılmasının əhatə dairəsi haqqında özünüzə məlumat verin.",
      "work.noRanking": "Cari iş seçimi tövsiyə olunan ilk 5 iş və ya işə qəbul üçün uyğunluğun müəyyən edilməsi deyil. Bu, təyin olunmuş faktiki işə əsaslanaraq dəstək metodunu və fəaliyyət planını müəyyən edən funksiyadır.",
